INSERT INTO Playbooks (playbook_id, name, applicable_incident_type, steps_description, created_by) VALUES
  (1, 'Phishing triage', 'phishing', '1. Pull the message and headers. 2. Block sender and URLs. 3. Find recipients who clicked. 4. Reset exposed credentials. 5. Notify users.', 1),
  (2, 'Business email compromise', 'bec', '1. Freeze the payment. 2. Verify the request out of band. 3. Check mailbox rules and sign-ins. 4. Contact the bank. 5. Report.', 2),
  (3, 'Ransomware response', 'ransomware', '1. Isolate affected hosts. 2. Disable the accounts involved. 3. Identify the encryptor and scope. 4. Restore from clean backups. 5. Post-incident review.', 1),
  (4, 'Brute force and spraying', 'brute_force', '1. Block the sources. 2. Check for any successful logins. 3. Enforce lockout and MFA. 4. Review exposed services.', 2),
  (5, 'Credential stuffing', 'credential_stuffing', '1. Rate-limit the login endpoint. 2. Identify accessed accounts. 3. Force password resets. 4. Notify affected customers.', 1),
  (6, 'Malware containment', 'malware', '1. Isolate the endpoint. 2. Collect the sample and hash. 3. Sweep the fleet for the hash. 4. Reimage. 5. Block callbacks.', 2),
  (7, 'Resource abuse (cryptomining)', 'cryptomining', '1. Kill the process. 2. Find the persistence. 3. Rotate exposed keys. 4. Patch the entry point.', 1),
  (8, 'Data exfiltration', 'exfiltration', '1. Preserve logs. 2. Quantify what left. 3. Revoke access. 4. Involve legal and privacy. 5. Notify if required.', 2),
  (9, 'Web application attack', 'web', '1. Block the attacking sources at the WAF. 2. Check for web shells. 3. Patch the vulnerable code. 4. Review database access.', 1),
  (10, 'Command-and-control beaconing', 'c2', '1. Sinkhole or block the destination. 2. Isolate the host. 3. Identify the implant. 4. Hunt for the same beacon elsewhere.', 2),
  (11, 'Cloud misconfiguration', 'cloud', '1. Remove public access. 2. Review access logs. 3. Rotate any exposed secrets. 4. Add a policy guardrail.', 1),
  (12, 'DDoS mitigation', 'ddos', '1. Engage upstream scrubbing. 2. Rate-limit at the edge. 3. Scale the affected service. 4. Review after traffic normalises.', 2);
