-- incident 1 (web_exploitation)
SET @sentinel_actor = 8, @sentinel_clock = '2026-01-07 06:07:00';
INSERT INTO Incidents (incident_id, title, narrative, severity, reported_by) VALUES (1, 'Path traversal requests against customer-portal', 'Error logs on customer-portal filled with database errors after a scan from one address. The uploaded script accepted commands through a hidden parameter; its hash is https://files-mail52.invalid/invoice/a821d09a. The vulnerable component was a plugin two major versions behind. The web shell was used to list directories but not to move further.', 'high', 8);
SET @sentinel_clock = '2026-01-07 06:24:00';
INSERT INTO Incident_IOC (incident_id, ioc_id, notes) VALUES (1, 202, 'Exploit request path');
INSERT INTO Incident_IOC (incident_id, ioc_id, notes) VALUES (1, 203, 'Attacking source');
INSERT INTO Incident_Asset (incident_id, asset_id, impact_description) VALUES (1, 14, NULL);
SET @sentinel_actor = 2, @sentinel_clock = '2026-01-07 08:42:00';
CALL reassign_incident(1, 6, 'Triage: on shift');
SET @sentinel_actor = 6, @sentinel_clock = '2026-01-07 09:29:00';
CALL transition_incident(1, 'investigating', NULL);
SET @sentinel_clock = '2026-01-07 15:21:00';
INSERT INTO Notes (incident_id, author_id, content) VALUES (1, 6, 'Searched the web root for other unexpected files.');
SET @sentinel_clock = '2026-01-07 18:06:00';
INSERT INTO Notes (incident_id, author_id, content) VALUES (1, 6, 'Reviewed web and database logs for successful payloads.');
SET @sentinel_clock = '2026-01-08 01:15:00';
INSERT INTO Notes (incident_id, author_id, content) VALUES (1, 6, 'Blocked the source at the firewall and removed the web shell.');
CALL transition_incident(1, 'contained', NULL);
SET @sentinel_clock = '2026-01-08 14:07:00';
UPDATE Incident_IOC SET review_status = 'confirmed' WHERE incident_id = 1 AND ioc_id = 202;
UPDATE Incident_IOC SET review_status = 'confirmed' WHERE incident_id = 1 AND ioc_id = 203;
UPDATE Incident_Asset SET impact_description = 'Public web application attacked' WHERE incident_id = 1 AND asset_id = 14;
SET @sentinel_clock = '2026-01-08 17:21:00';
INSERT INTO Notes (incident_id, author_id, content) VALUES (1, 6, 'Plugin patched and parameterised queries deployed.');
CALL transition_incident(1, 'resolved', NULL);
SET @sentinel_actor = 1, @sentinel_clock = '2026-01-09 12:34:00';
CALL close_incident(1, 'Evidence complete; closing');

-- incident 2 (data_exfiltration)
SET @sentinel_actor = 5, @sentinel_clock = '2026-01-09 11:14:00';
INSERT INTO Incidents (incident_id, title, narrative, severity, reported_by) VALUES (2, 'Bulk copy by departing employee', 'Data-loss monitoring flagged an upload of 55 gigabytes from crm-app to a file-sharing site. The transfer was split into small chunks to avoid volume alerts. The destination was 198.51.100.62. Project source code and design documents left the network.', 'medium', 5);
SET @sentinel_clock = '2026-01-09 11:16:00';
INSERT INTO Incident_IOC (incident_id, ioc_id, notes) VALUES (2, 180, 'Exfiltration destination');
INSERT INTO Incident_Asset (incident_id, asset_id, impact_description) VALUES (2, 20, NULL);
SET @sentinel_actor = 1, @sentinel_clock = '2026-01-09 20:17:00';
CALL reassign_incident(2, 7, 'Triage: matches recent work');
SET @sentinel_actor = 7, @sentinel_clock = '2026-01-09 21:16:00';
CALL transition_incident(2, 'investigating', NULL);
INSERT INTO Incident_Playbook (incident_id, playbook_id, applied_at) VALUES (2, 8, '2026-01-09 21:42:00');
SET @sentinel_clock = '2026-01-09 23:21:00';
