SET @sentinel_clock = '2026-01-10 20:57:00';
INSERT INTO Notes (incident_id, author_id, content) VALUES (2, 7, 'Legal and privacy informed; access review completed.');
CALL transition_incident(2, 'resolved', NULL);
SET @sentinel_actor = 2, @sentinel_clock = '2026-01-13 03:23:00';
CALL close_incident(2, 'Closed after review');

-- incident 3 (cryptomining)
SET @sentinel_actor = 6, @sentinel_clock = '2026-01-10 14:36:00';
INSERT INTO Incidents (incident_id, title, narrative, severity, reported_by) VALUES (3, 'Unexpected CPU load on build-01', 'Network monitoring saw a server opening long-lived connections to an unknown service. Access came through an exposed management interface with no password. An unknown process was connecting to the mining pool support-auth76.example. The cluster ran extra nodes for about 14 hours.', 'medium', 6);
SET @sentinel_clock = '2026-01-10 14:56:00';
INSERT INTO Incident_IOC (incident_id, ioc_id, notes) VALUES (3, 169, 'Mining pool');
INSERT INTO Incident_Asset (incident_id, asset_id, impact_description) VALUES (3, 6, NULL);
SET @sentinel_actor = 2, @sentinel_clock = '2026-01-10 19:08:00';
CALL reassign_incident(3, 6, 'Triage: on shift');
SET @sentinel_actor = 6, @sentinel_clock = '2026-01-10 19:14:00';
CALL transition_incident(3, 'investigating', NULL);
INSERT INTO Incident_Playbook (incident_id, playbook_id, applied_at) VALUES (3, 7, '2026-01-10 19:48:00');
SET @sentinel_clock = '2026-01-11 01:41:00';
INSERT INTO Notes (incident_id, author_id, content) VALUES (3, 6, 'Found the persistence and the process tree.');
SET @sentinel_clock = '2026-01-11 05:47:00';
INSERT INTO Notes (incident_id, author_id, content) VALUES (3, 6, 'Checked the service account for other activity.');
SET @sentinel_clock = '2026-01-12 08:59:00';
INSERT INTO Notes (incident_id, author_id, content) VALUES (3, 6, 'Killed the process and removed the scheduled job.');
CALL transition_incident(3, 'contained', NULL);

-- incident 4 (c2_beaconing)
SET @sentinel_clock = '2026-01-13 07:09:00';
INSERT INTO Incidents (incident_id, title, narrative, severity, reported_by) VALUES (4, 'Beaconing workstation', 'Network monitoring flagged ws-eng-34 contacting the same external domain at regular intervals. The process injected itself into a browser to blend in. The small encrypted payloads are consistent with command-and-control check-ins. Two other hosts showed the same beacon pattern.', 'high', 6);
SET @sentinel_clock = '2026-01-13 07:22:00';
INSERT INTO Incident_Asset (incident_id, asset_id, impact_description) VALUES (4, 26, NULL);
SET @sentinel_actor = 1, @sentinel_clock = '2026-01-13 08:26:00';
