SET @sentinel_actor = 8, @sentinel_clock = '2026-01-13 08:45:00';
CALL transition_incident(4, 'investigating', NULL);
SET @sentinel_clock = '2026-01-13 12:13:00';
INSERT INTO Notes (incident_id, author_id, content) VALUES (4, 8, 'Hunted for the same destination across DNS logs.');
SET @sentinel_clock = '2026-01-14 02:19:00';
INSERT INTO Notes (incident_id, author_id, content) VALUES (4, 8, 'Sinkholed the domain and isolated the host.');
CALL transition_incident(4, 'contained', NULL);
SET @sentinel_clock = '2026-01-15 08:59:00';
UPDATE Incident_Asset SET impact_description = 'Endpoint under remote control' WHERE incident_id = 4 AND asset_id = 26;
SET @sentinel_clock = '2026-01-15 09:36:00';
INSERT INTO Notes (incident_id, author_id, content) VALUES (4, 8, 'Implant removed; host reimaged.');
CALL transition_incident(4, 'resolved', NULL);
SET @sentinel_actor = 2, @sentinel_clock = '2026-01-16 17:10:00';
CALL close_incident(4, 'Reviewed and closed');

-- incident 5 (cloud_misconfiguration, cloud_misconfiguration#25)
SET @sentinel_actor = 7, @sentinel_clock = '2026-01-19 23:07:30';
INSERT INTO Incidents (incident_id, title, narrative, severity, reported_by) VALUES (5, 'Access key committed to a public repository', 'Secret scanning found a cloud access key in a public code repository. The key had administrator rights and was valid for 6 hours after the commit. The public link 192.0.2.157 had been indexed by a search engine. No access other than our own was found in the logs.', 'high', 7);
